client.on('ready', () => {
  console.log(`Bot ${client.user.tag} is ready!`);
});

client.login(DISCORD_TOKEN);
```

8. Erstellen Sie eine neue Datei mit dem Namen `commands/banCommand.js` und fügen Sie folgendes Code hinzu:

```javascript
const { Command } = require('discord.js-commando');

module.exports = class BanCommand extends Command {
  constructor(client) {
    super(client, {
      name: 'ban',
      group: 'moderation',
      memberName: 'ban',
      description: 'Bans a user from the server.',
      guildOnly: true,
      options: [
        {
          name: 'user',
          description: 'The user to ban.',
          type: 'USER',
          required: true,
        },
      ],
    });
