  async run(message, { user }) {
    const member = message.guild.members.cache.get(user.id);

    await message.member.permissions.has('BanMembers')
      ? member.ban()
      : message.reply('Du hast keine Berechtigung, dieses Mitglied zu bannen.');

    message.reply(`${user.tag} wurde gebannt.`);
