      margin-top: 5px;
    }
  </style>
</head>
<body>
  <button id="show-modal">Show Fake Chatbot</button>

  <!-- Modal -->
  <div id="myModal" class="modal">
    <div class="modal-content">
      <h2>Fake Chatbot</h2>
      <div id="chat-log"></div>
    </div>
  </div>

  <!-- JavaScript für das Modal -->
  <script>
    // Get the modal
    var modal = document.getElementById("myModal");

    // Get the <span> element that closes the modal
    var span = document.getElementsByClassName("close")[0];

    // Get the <div> element that contains the chat log
    var chatLog = document.getElementById("chat-log");

    // When the user clicks the button, open the modal
    document.getElementById("show-modal").onclick = function() {
      modal.style.display = "block";
    }

    // When the user clicks on <span> (x), close the modal
    span.onclick = function() {
      modal.style.display = "none";
    }

    // When the user clicks anywhere outside of the modal, close it
    window.onclick = function(event) {
      if (event.target == modal) {
        modal.style.display = "none";
      }
    }

    // Example chat messages (replace with your own data)
    var messages = [
      { type: 'user', text: 'Hello, how can I help you today?' },
      { type: 'bot', text: 'Hi there! I am your virtual assistant. How can I assist you?' },
      { type: 'user', text: 'Can you provide me with the latest news?' },
      { type: 'bot', text: 'Sure! Here are the latest news headlines: [News headlines]' }
    ];

    // Render chat messages in the modal
    function renderChatMessages() {
      chatLog.innerHTML = '';
      messages.forEach(function(message) {
        var className = message.type === 'user' ? 'message__user' : 'message__bot';
        var element = document.createElement('div');
        element.classList.add('message');
        element.innerHTML = `
          <div class="${className}">${message.text}</div>
          <div class="message__timestamp">${new Date().toLocaleTimeString()}</div>
        `;
        chatLog.appendChild(element);
      });
    }

    // Render initial chat messages
    renderChatMessages();
  </script>
</body>
</html>
