```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    // Spezifizieren Sie den Dateinamen und das Suchwort
    string filename = "input.txt";
    string search_word = "suchwort";

    // Öffnen Sie die Datei
    ifstream file(filename);

    // Prüfen Sie, ob die Datei erfolgreich geöffnet wurde
    if (!file.is_open()) {
        cerr << "Fehler beim Öffnen der Datei: " << filename << endl;
        return 1;
    }

    // Variablen zum Zählen des Suchworts
    int word_count = 0;

    // Zeilenweise lesen der Datei
    string line;
    while (getline(file, line)) {
        // Trennen der Zeile in einzelne Wörter
        size_t pos = 0;
        string token;
        while ((pos = line.find(" ")) != string::npos) {
            token = line.substr(pos, line.find(" ") - pos);
            line.erase(pos, line.find(" ") + 1);
            if (token == search_word) {
                word_count++;
            }
        }
        // Letztes Wort der Zeile überprüfen
        if (line == search_word) {
            word_count++;
        }
    }

    // Schließen der Datei
    file.close();

    // Ausgabe der Ergebnisse
    cout << "Das Suchwort '" << search_word << "' kommt " << word_count << " mal in der Datei " << filename << " vor." << endl;

    return 0;
}
